INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (0, 'Antasida Doen Tablet Kunyah', 'Lambung', 'Obat sakit maag untuk mengurangi nyeri lambung yang disebabkan oleh kelebihan asam lambung dengan gejala seperti mual, perih kembung.', 'Box, Strip', 2000, 'Strip: Rp2.000; Box: Rp16.000', 'Sebaiknya diberikan pada saat perut kosong; Berikan 1-2 jam setelah makan sebelum tidur; Kunyah tablet degan baik sebelum ditelan', 'Dewasa: 1-2 tablet, 3-4 kali per hari.; Anak 6-12 tahun: 0.5-1 tablet, 3-4 kali per hari', 'kadang-kadang terjadi konstipasi, diare; Mual, muntah; Hypophosphatemia osteomalacia (pada pemberian dosis besar untuk jangka lama bila kadar phosphate rendah); Dialysis dementis pada pemberian jangka panjang pada pasien dialisis', 'Aluminium hydroxide akan mengurangi absorpsi bermacam- macam vitamin Tetracyclin', 'Jangan digunakan selama 2 minggu', 'Aluminium Hydroxide 200 mg; Magnesium Hydroxide 200 mg', 'Disfungsi ginjal berat; hipersensitif; obstruksi saluran pencernaan; pasien yang sangat lemah', 'obat_0.png', NULL, 'https://tse.mm.bing.net/th?q=Antasida%20Doen%20Tablet%20Kunyah%20obat%20kemasan', 'Lambung', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (1, 'Dexanta Tablet Kunyah', 'Lambung', 'Mengurangi gejala kelebihan asam lambung, gastritis, tukak lambung, tukak usus dua belas jari seperti mual, nyeri lambung, nyeri ulu hati, kembung perasaan penuh pada lambung', 'Box, Strip', 3000, 'Strip: Rp3.000; Box: Rp30.000', 'Diberikan diantara waktu makan; Tablet dikunyah sampai halus sebelum ditelan', 'all: 3 x sehari 1-2 tablet kunyah', 'Konstipasi; diare; mual; muntah; Gejala akan hilang bila pemakaian obat dihentikan', 'Pemberian bersama dengan cimetidine atau tetracycline dapat mengurangi absorpsi cimetidine atau tetracycline', 'bukan untuk dikonsumsi secara rutin atau jangka panjang', 'Aluminium Hydroxide 200 mg; Magnesium Hydroxide 200 mg; Simethicone 50 mg', 'Tidak boleh diberikan pada pasien dengan gangguan fungsi ginjal yang berat', 'obat_1.png', NULL, 'https://tse.mm.bing.net/th?q=Dexanta%20Tablet%20Kunyah%20obat%20kemasan', 'Lambung', NULL);
