INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (3, 'Gastrucid Cair', 'Lambung', 'Mengurangi gejala kelebihan asam lambung, gastritis, tukak lambung, tukak usus dua belas jari seperti mual, nyeri lambung, nyeri ulu hati, kembung perasaan penuh pada lambung', NULL, 0, NULL, 'Diminum 1 jam sebelum makan atau 2 jam setelah makan menjelang tidur.', 'Dewasa: 3-4 kali sehari 1-2 sendok takar 5-10 ml; Anak-anak 6-12 tahun: 3-4 kali sehari 12-1 sendok takar 2.5-5 ml', 'efek_samping yang umum adalah sembelit; diare; mual; muntah; gejala-gejala tersebut akan hilang bila pemakaian obat dihentikan', 'Pemberian bersama-sama dengan Cimetidine atau Tetracycline dapat mengurangi absorpsi obat tersebut', 'Tidak dianjurkan digunakan terus menerus lebih dari 2 minggu, kecuali atas petunjuk dokter karena dapat menimbulkan ketergantungan fungsi lambung', 'Aluminium Hydroxide 325 mg; Magnesium Hydroxide 325 mg; Simethicone 50 mg', 'Jangan diberikan pada penderita gangguan fungsi ginjal yang berat; karena dapat menimbulkan hipermagnesia kadar magnesium dalam darah meningkat', 'obat_3.png', NULL, 'https://tse.mm.bing.net/th?q=Gastrucid%20Cair%20obat%20kemasan', 'Lambung', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (4, 'Gastrucid Tablet Kunyah', 'Lambung', 'Mengurangi gejala kelebihan asam lambung, gastritis, tukak lambung, tukak usus dua belas jari seperti mual, nyeri lambung, nyeri ulu hati, kembung perasaan penuh pada lambung', 'Box, Strip', 4500, 'Strip: Rp4.500; Box: Rp41.500', '1 jam sesudah makan sebelum tidur malam, tablet dikunyah sampai halus sebelum ditelan', 'all: 3 x sehari 1-2 tablet kunyah', 'efek_samping yang umum adalah sembelit; diare; mual; muntah; gejala-gejala tersebut akan hilang bila pemakaian obat dihentikan.', 'Pemberian bersama-sama dengan Cimetidine atau Tetracycline dapat mengurangi absorpsi obat tersebut', 'Tidak dianjurkan digunakan terus menerus lebih dari 2 minggu, kecuali atas petunjuk dokter karena dapat menimbulkan ketergantungan fungsi lambung', 'Aluminium Hydroxide 325 mg; Magnesium Hydroxide 325 mg; Simethicone 50 mg', 'Jangan diberikan pada penderita gangguan fungsi ginjal yang berat; karena dapat menimbulkan hipermagnesia kadar magnesium dalam darah meningkat', 'obat_4.png', NULL, 'https://tse.mm.bing.net/th?q=Gastrucid%20Tablet%20Kunyah%20obat%20kemasan', 'Lambung', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (5, 'Mylanta Cair', 'Lambung', 'Untuk mengurangi gejala-gejala yang berhubungan dengan kelebihan asam lambung, gastritis, tukak lambung, tukak usus dua belas jari, dengan gejala- gejala seperti mual, nyeri lambung, nyeri ulu hati', 'Cair 150 Ml, Cair 50 Ml', 17500, 'Cair 50 Ml: Rp17.500; Cair 150 Ml: Rp46.500', 'Dikonsumsi 1 jam sebelum makan atau 2 jam sesudah makan menjelang tidur', 'Dewasa: 1-2 sendok takar 5-10 mL 3-4 kali sehari; Anak-anak 6 - 12 tahun: 12 - 1 sendok takar 2.5 - 5 mL, sebanyak 3-4 kali sehari', 'efek_samping yang umum adalah sembelit; diare; mual; muntah; sensasi terbakar di mulut atau tenggorokan; dysgeusia atau persepsi rasa berubah; reaksi hipersensitifitas termasuk ruam; urtikaria; angioedema. Gejala-gejala tersebut akan hilang bila pemakaian obat dihentikan', 'Kecuali atas anjuran dokter, jangan digunakan dalam 2 jam setelah mengkonsumsi obat lain terutama Simetidin Tetrasiklin hindari minuman yang mengandung asam sari buah, wine, dll karena dapat mempengaruhi penyerapan obat. Pasien harus berkonsultasi ke dokter sebelum menggunakan produk ini bersamaan dengan Raltegravir, Dolutegravir, Elvitegravir', 'Tidak dianjurkan untuk digunakan secara terus menerus selama lebih dari 2 minggu, kecuali atas petunjuk dokter', 'Aluminium hidroksida kering 200 mg; Magnesium hidroksida 200 mg; Simetikon 20 mg', 'Jangan diberikan pada penderita gangguan fungsi ginjal yang berat, karena dapat menimbulkan hipermagnesia (kadar magnesium dalam darah meningkat); Tidak boleh digunakan pada pasien yang hipersensitif terhadap aluminium hidroksida, magnesium hidroksida, simetikon atau komponen lain dalam formulasi obat ini', 'obat_5.png', NULL, 'https://tse.mm.bing.net/th?q=Mylanta%20Cair%20obat%20kemasan', 'Lambung', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (6, 'Mylanta Tablet Kunyah', 'Lambung', 'Untuk mengurangi gejala-gejala yang berhubungan dengan kelebihan asam lambung, gastritis, tukak lambung, tukak usus dua belas jari, dengan gejala- gejala seperti mual, nyeri lambung, nyeri ulu hati', 'Box, Strip', 9000, 'Strip: Rp9.000; Box: Rp87.500', 'Diminum 1 jam sebelum makan atau 2 jam setelah makan menjelang tidur, sebaiknya dikunyah dahulu', 'Dewasa: 1-2 tablet, diberikan 3-4 kali sehari.; Anak-anak 6-12 tahun: 0.5-1 tablet, diberikan 1-2 kali sehari', 'efek_samping yang umum adalah sembelit; diare; mual; muntah; sensasi terbakar di mulut atau tenggorokan; dysgeusia atau persepsi rasa berubah; reaksi hipersensitifitas termasuk ruam; urtikaria; angioedema. Gejala-gejala tersebut akan hilang bila pemakaian obat dihentikan', 'Kecuali atas anjuran dokter, jangan digunakan dalam 2 jam setelah mengkonsumsi obat lain terutama Simetidin Tetrasiklin hindari minuman yang mengandung asam sari buah, wine, dll karena dapat mempengaruhi penyerapan obat. Pasien harus berkonsultasi ke dokter sebelum menggunakan produk ini bersamaan dengan Raltegravir, Dolutegravir, Elvitegravir', 'Obat ini dapat bekerja cepat, tetapi tidak boleh digunakan untuk jangka panjang', 'Aluminium hidroksida kering 200 mg; Magnesium hidroksida 200 mg; Simetikon 20 mg', 'Jangan diberikan pada penderita gangguan fungsi ginjal yang berat, karena dapat menimbulkan hipermagnesia (kadar magnesium dalam darah meningkat); Tidak boleh digunakan pada pasien yang hipersensitif terhadap aluminium hidroksida, magnesium hidroksida, simetikon atau komponen lain dalam formulasi obat ini', 'obat_6.png', NULL, 'https://tse.mm.bing.net/th?q=Mylanta%20Tablet%20Kunyah%20obat%20kemasan', 'Lambung', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (7, 'New Enzyplex Tablet', 'Lambung', 'Membantu proses pencernaan, bermanfaat mencegah mengatasi gangguan pencernaan seperti rasa sebah, kembung, rasa penuh pada lambung keadaan-keadaan dimana dibutuhkan peningkatan enzim pencernaan seperti makan terlalu banyak, intoleransi terhadap makanan, salah cerna lain-lain gangguan pencernaan fungsional', 'All', 11500, 'All: Rp11.500', 'Pada waktu makan, sesudah makan atau sesuai anjuran petunjuk dokter', 'all: 1-2 tablet per hari', 'efek_samping yang paling sering terjadi adalah Ketidaknyamanan perut; Konstipasi Dermatitis; Reaksi gastrointestinal lainnya yang jarang terjadi adalah Diarea; Mulas; Mual dan Muntah; Dapat terjadi reaksi hipersensitifitas', 'Konsumsi vitamin B6 di atas 5-10 mg per hari dapat mengurangi efektivitas levodopa; Mempengaruhi durasi altretamine dan meningkatkan fotosensitifitas yang diinduksi oleh amiodaron, dan mengurangi konsentrasi fenitoin', NULL, 'Amilase 10000 sat; Protease 9000 sat; Lipase 240 sat; Asam desoksikholat 30 mg; Dimetilpolisiloksan 25 mg; Vitamin b1 10 mg; Vitamin b2 5 mg; Vitamin b6 5 mg; Vitamin b12 5 mg; Niasinamid 10 mg; Kalsium Pantotenat 5 mg', 'Hipersensitif terhadap salah satu komponen obat; Kontraindikasi untuk pasien yang sedang mengalami pankreatitis akut atau eksaserbasi pankreatitis kronis akut; Kontraindikasi untuk pasien yang menggunakan antikoagulan', 'obat_7.png', NULL, 'https://tse.mm.bing.net/th?q=New%20Enzyplex%20Tablet%20obat%20kemasan', 'Lambung', NULL);
