INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (37, 'Woods Peppermint Antitussive', 'Batuk', 'Batuk tidak berdahak yang disertai alergi', 'Cair 100 Ml, Cair 60 Ml', 22500, 'Cair 60 Ml: Rp22.500; Cair 100 Ml: Rp36.000', 'Sesudah makan', 'Dewasa dan anak 12 tahun: 3 x sehari, 10 ml; Anak-anak 6-12 tahun: 3 x sehari, 5 ml', 'efek_samping yang timbul seperti rasa mual; pusing; mengantuk dan konstipasi', 'Penggunaan secara bersamaan dengan inhibitor MAO dapat menyebabkan stimulasi CNS dan depresi pernapasan berat', 'Wood Pepermint bukan untuk dikonsumsi secara berulang-ulang atau dalam jangka panjang', 'Dextromethorphan HBr 7.5 mg; Diphenhydramine HCL 12.5 mg', 'Pada wanita hamil dan menyusui; penderita hipersensitif terhadap salah satu bahan aktif; penderita glaucoma; asma bronkhial; kegagalan pernapasan sebaiknya tidak menggunakan obat ini', 'obat_37.png', NULL, 'https://tse.mm.bing.net/th?q=Woods%20Peppermint%20Antitussive%20obat%20kemasan', 'Batuk', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (38, 'Zenirex', 'Batuk', 'Untuk meredakan batuk berdahak atau batuk yang disebabkan oleh alergi', 'All', 8000, 'All: Rp8.000', 'Kocok terlebih dahulu', 'Dewasa: sehari 2 - 4 sendok teh tiap 4 jam', 'Menimbulkan rasa mengantuk. Kadang-kadang penglihatan kabur; mulut kering; meningkatnya tekanan darah; mual muntah; diare; iritasi saluran cerna', NULL, 'Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan hati', 'Promethazine HCL 5 mg; Ipecacuanhae Extractum 4 mg; Guaifenesin 50 mg', 'Hipersensitif; anak-anak < 2 tahun; menggunakan lebih dari satu obat batuk dan flu; penyakit ginjal; penyakit hati; anak-anak dengan disentri parah', 'obat_38.png', NULL, 'https://tse.mm.bing.net/th?q=Zenirex%20obat%20kemasan', 'Batuk', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (39, 'Decolsin Cair', 'Batuk Dan Flu', 'Untuk meredakan batuk yang menyertai gejala-gejala flu seperti demam, sakit kepala, hidung tersumbat dan bersin-bersin', 'All', 19500, 'All: Rp19.500', 'Sebelum atau sesudah makan', 'Anak 6-12 tahun: 5 mL 1 sendok takar; Dewasa dan anak 12 tahun: 10 mL 2 sendok takar Anak 2-6 tahun Atas petunjuk Dokter', 'Mengantuk; gangguan pencernaan; gangguan psikomotor; takikardia; aritmia; mulut kering; palpitasi; retensi urin; Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan hati', 'Penggunaan bersamaan antidepresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'Produk ini biasanya tidak boleh digunakan untuk batuk berkelanjutan akibat merokok atau masalah pernapasan jangka panjang seperti bronkitis', 'Paracetamol 250 mg; Pseudoephedrine HCI 15 mg; Chlorphenamine Maleate 1 mg; Dextromethorphan HBr 5 mg; Guaifenesin 50 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita yang hipersensitif terhadap komponen obat ini; Penderita dengan gangguan fungsi hati yang berat; Penderita dengan gangguan jantung dan diabetes melitus', 'obat_39.png', NULL, 'https://tse.mm.bing.net/th?q=Decolsin%20Cair%20obat%20kemasan', 'Batuk, Flu', NULL);
