INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (73, 'Decolgen Kids Flu', 'Flu', 'Untuk meringankan gejala flu seperti demam, sakit kepala, bersin-bersin dan hidung tersumbat', 'All', 13000, 'All: Rp13.000', 'sebelum atau sesudah makan', 'Anak 6-12 tahun: 10 mL 2 sendok takar, 3 kali sehari; Dewasa dan anak 12 tahun: 20 mL 4 sendok takar, 3 kali sehari', 'Mengantuk; gangguan pencernaan; insomnia; gelisah; eksitasi; tremor; takikardia; aritmia; ventrikel; mulut kering; palpitasi; retensi urin; Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan hati', 'Penggunaan bersamaan dengan obat antidepresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'sebaiknya Anda tidak mengonsumsi obat jangka panjang untuk mengatasi gejala agar terhindar dari risiko bahaya pada tubuh', NULL, 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan riwayat hipersensitif Paracetamol, Penderita dengan riwayat hipersensitif Paracetamol, Penderita dengan riwayat hipersensitif Paracetamol, Pseudoephedrine HCl, Chlorphenamine Maleate dan Guaiafenesin; Penderita dengan gangguan fungsi hati yang berat', 'obat_73.png', NULL, 'https://tse.mm.bing.net/th?q=Decolgen%20Kids%20Flu%20obat%20kemasan', 'Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (74, 'Triaminic Pilek', 'Pilek', 'Meringankan bersin-bersin dan Melegakan hidung tersumbat karena pilek', 'All', 83500, 'All: Rp83.500', 'sebelum atau sesudah makan', 'Usia 2-6 tahun: 12 Sendok takar 2,5 ml 3 x Sehari; Diatas 6-12 tahun: 1 Sendok takar 5 ml 3 x Sehari; Diatas 12 tahun: 2 Sendok takar 10 ml 3 x Sehari', 'Chlorphenamine maleate dapat menyebabkan kantuk dan mulut kering; Pseudoephedrine HCl dapat menyebabkan perasaan mabuk gamang; nyeri kepala; mual; muntah; berkeringat; haus; takikardia; nyeri prekordial; palpitasi; kesulitan berkemih; kelemahan otot dan tremor; kecemasan; kegelisahan; insomnia kesulitan tidur; hipertensi; mulut kering; midriasis pembesaran pupil dan permasalahan lambung; Aritmia ventrikular dapat terjadi; Pada pasien-pasien dengan pembesaran prostat dapat menyebabkan kesulitan berkemih', 'Penggunaan bersamaan dengan inhibitor penghambat monoamin oksidase di kontra-indikasikan; Penggunaan bersamaan dapat memperpanjang dan meningkatkan efek-efek Pseudoephedrine HCI pada perangsangan jantung dan vasopresor, yang berakibat pada krisis hipertensi danatau krisis hiperpireksia. Interaksi ini masih mungkin berlanjut sampai 2 minggu setelah penggunaan inhibitor penghambat MAO; Pseudoephedrine HCl dapat mengurangi efek beberapa zat obat antihipertensi guanetidin dan turunannya; Pseudoephedrine HCI dapat berinteraksi dengan obat-obat anestesi berhalogen; Efek pengobatan yang bekerja sentral simpatomimetika, antidepresi dapat ditingkatkan oleh Pseudoephedrine HCI atau Chlorphenamine maleate', 'Tidak semua orang boleh menggunakan obat ini dalam jangka waktu lama', NULL, 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita hipersensitif terhadap komponen obat ini; Penderita gangguan jantung dan diabetes mellitus', 'obat_74.png', NULL, 'https://tse.mm.bing.net/th?q=Triaminic%20Pilek%20obat%20kemasan', 'Pilek', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (75, 'Rhinos Junior', 'Pilek', 'Meringankan bersin-bersin dan hidung tersumbat karena pilek', 'All', 64500, 'All: Rp64.500', 'dapat diberikan bersama atau tanpa makanan', 'Dewasa dan anak-anak lebih dari 12 tahun: 10 ml, tiga kali sehari; Anak-anak 6-12 tahun: 5 ml, tiga kali sehari; Anak-anak 2-5 tahun: 2,5 ml, tiga kali sehari; Anak-anak di bawah 2 tahun: atas petunjuk dokter', 'Insomnia; Sakit kepala; Gemetar; Takikardia detak jantung melebihi 100 kali per menit; Aritmia gangguan irama jantung; Jantung berdebar; Kesulitan buang air kecil', 'Hindari penggunaan bersamaan dengan obat antidepresan golongan MAOI dapat menyebabkan hipertensi; Informasikan pada dokter jika sedang mengonsumsi suplemen, obat lain atau produk herbal', 'Obat ini hanya boleh digunakan untuk jangka pendek', 'Pseudoephedrine HCl 15 mg; Chlorphenamine maleate 1 mg', 'Hindari penggunaan Rhinos Junior pada pasien - Pasien yang peka terhadap obat simpatomimetik lain misalnya efedrin, fenilpropanolamin, fenilefrin, penderita hipertensi berat; Pasien yang mendapat terapi obat antidepresan tipe penghambat MAO; Hipertensi berat atau dengan potensi untuk mengembangkan hipertensi atau stroke', 'obat_75.png', NULL, 'https://tse.mm.bing.net/th?q=Rhinos%20Junior%20obat%20kemasan', 'Pilek', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (76, 'Rhinos Neo', 'Pilek', 'Meringankan hidung tersumbat karena pilek', 'All', 72000, 'All: Rp72.000', 'sebelum atau sesudah makan', 'Anak-anak 2-5 tahun: 2 x 0,4 ml larutan 0,8 ml, tiga kali sehari; Anak-anak di bawah 2 tahun: atas petunjuk dokter', 'Insomnia; sakit kepala; eksitasi; tremor; takikardi; aritmia; palpitasi; kesulitan berkemih', 'Penggunaan Rhinos Neo bersama dengan obat antidepresan golongan MAOI dapat menyebabkan hipertensi; Beritahu dokter jika kamu sedang mengonsumsi suplemenobat kimia, atau produk herbal lain untuk menghindari risiko interaksi', 'Obat ini hanya boleh digunakan untuk jangka pendek', 'Pseudoephedrine HCI 7.5 mg', 'Hindari penggunaan obat Rhinos Neo pada pasien; Peka terhadap obat simpatomimetik lain misalnya ephedrin, fenilpropanolamin, fenilefrin, penderita hipertensi berat; Diterapi obat antidepresan tipe penghambat MAO; Hipertensi berat atau dengan potensi untuk mengembangkan hipertensi atau stroke', 'obat_76.png', NULL, 'https://tse.mm.bing.net/th?q=Rhinos%20Neo%20obat%20kemasan', 'Pilek', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (77, 'Hufagripp Pilek', 'Pilek', 'Untuk meringankan bersin-bersin dan hidung tersumbat karena pilek', 'All', 16000, 'All: Rp16.000', 'sesudah makan', 'Anak usia 2-6 tahun: 3 x sehari 1/2 sendok takar 2,5 ml; Anak usia 6-12 tahun: 3 x sehari 1 sendok takar 5 ml; Dewasa dan anak 12 tahun: 3 x sehari 2 sendok takar 10 ml', 'Mengantuk; insomnia; eksitasi; takikardia; aritmia ventrikel; tremor; palpitasi; mulut kering; retensi urine dan gangguan saluran cerna', 'Penggunaan bersamaan dengan anti depresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'konsumsi dalam jangka panjang akan berpengaruh ke tubuh', 'Pseudoephedrine HCI 15 mg; Chlorphenamine Maleate 1 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita yang hipersensitif terhadap komponen obat ini', 'obat_77.png', NULL, 'https://tse.mm.bing.net/th?q=Hufagripp%20Pilek%20obat%20kemasan', 'Pilek', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (78, 'Bisolvon Tablet', 'Batuk', 'BISOLVON bekerja sebagai mukolitik untuk meredakan batuk berdahak', 'Box, Strip, Tablet', 3000, 'Tablet: Rp3.000; Strip: Rp27.000; Box: Rp269.000', 'Berikan sesudah makan', 'Dewasa & Anak > 12 th: 3 x 1 tablet sehari; Anak 6-12 tahun: 3 x 1/2 tablet sehari; Anak 2-6 tahun: 2 x 1/2 tablet sehari', 'Reaksi sensitif kekebalan tubuh; Gangguan sistem pencernaan; Gangguan kulit seperti ruam; Gangguan pernapasan', 'Tidak ada laporan interaksi klinis yang tidak menyenangkan dengan obat ini', 'Jangan menggunakan obat lebih dari 14 hari tanpa anjuran dari dokter', 'Bromheksin HCl 8 mg', 'BISOLVON tidak boleh digunakan oleh penderita yang hipersensitif terhadap bromheksin HCl atau komponen lain dalam formula; Pada kasus tertentu yang sifatnya jarang yaitu kondisi dimana terdapat ketidakcocokan dengan zat tambahan yang terkandung dalam produk obat tersebut penggunaan produk dikontraindikasikan', 'obat_78.png', NULL, 'https://tse.mm.bing.net/th?q=Bisolvon%20Tablet%20obat%20kemasan', 'Batuk', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (79, 'Acetylcysteine', 'Batuk', 'Mengencerkan dahak di saluran pernafasan', 'Box, Kapsul, Strip', 2000, 'Kapsul: Rp2.000; Strip: Rp17.000; Box: Rp164.000', 'Dikonsumsi setelah makan', 'Dewasa dan anak usia di atas 14 tahun: 1 kapsul 2-3 x sehari setara dengan 400-600 mg NAChari; Anak usia 6-14 tahun: 1 kapsul 2 x sehari setara dengan 400 mg NAChari; Anak usia di atas 6 tahun: 1 kapsul 3 x sehari setara dengan 600 mg NAChari; Anak di bawah 6 tahun: pertimbangkan penggunaan sediaan lain yang sesuai', 'efek_samping yang mungkin timbul namun jarang adalah pyrosis, nausea, vomiting, dan diarrhoea. Pada beberapa kasus terbatas terjadi stomatitis, pusing, dan telinga berdenging tinnitus; Setelah penggunaan NAC kadang terjadi reaksi alergi seperti itching, urticaria, cutaneous eruption rash, exanthema, sulit bernapas bronchospasm, denyut jantung yang cepat, dan hipotensi; Terjadinya kasus pada sebagian besar pasien dengan hiperreaktif pada sistem bronkial mengikuti bronkial asma disebut hyper responder, yaitu pasien dengan peningkatan sensitivitas akibat berbagai stimuli. Kemudian terjadi hemorrhage setelah pemberian NAC, berkaitan dengan reaksi hipersensitivitas secara individual; Tindakan yang harus diambil jika terjadi efek_samping mulai awal terjadinya reaksi hipersensitivitas, hentikan segera penggunaan NAC, konsultasikan ke dokter untuk tindakan selanjutnya berdasarkan tingkat keparahan penyakit', 'Penggunaan bersamaan dengan antitussive dapat menyebabkan penghentian sekresi yang berbahaya seiring berkurangnya batuk. Oleh sebab itu, kombinasi kedua obat ini dapat digunakan dengan beberapa perhatian; Penggunaan bersamaan dengan tetracycline HCI bagian dari doxycycline harus dilakukan dengan interval sekurangnya 2 jam. Hal ini tidak perlu dilakukan pada penggunaan bersamaan dengan Loracarbef; Penggunaan bersamaan dengan nitroglycerin kemungkinan dapat menyebabkan peningkatan efek vasodilating dan aliran darah dari nitroglycerin', 'hindari penggunaan jangka panjang', 'acetylcysteine 200 mg', 'Pasien hipersensitif terhadap acetylcysteine; Anak-anak di bawah 2 tahun', 'obat_79.png', NULL, 'https://tse.mm.bing.net/th?q=Acetylcysteine%20obat%20kemasan', 'Batuk', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (80, 'Guaifenesin', 'Batuk', 'Meredakan batuk berdahak sebagai ekspektoran', 'Box, Strip, Tablet', 500, 'Tablet: Rp500; Strip: Rp2.000; Box: Rp11.500', 'Sebelum atau sesudah makan', 'Dewasa: 2-4 tablet setiap 4 jam maksimum 24 tablet sehari; Anak 6 - 12 tahun: 1-2 tablet setiap 4 jam maksimum 12 tablet sehari; Anak 2 - 6 tahun: 21 tablet setiap 4 jam maksimum 6 tablet sehari', 'mual; muntah; diare dan nyeri perut bagian bawah; pusing; berkunang-kunang; sakit kepala; neprolithiasis; hipouricermia; ruam pada kulit', 'Interaksi guaifenesin dengan obat lain belum diketahui. Meski begitu, tidak menutup kemungkinan guaifenesin dapat berinteraksi dengan obat atau bahan aktif tertentu', 'tidak boleh dikonsumsin dalam jangka panjang', 'Guaifenesin 100 mg', 'Hipersensitif; diabetes; penyakit liver; fenilketouria; hamil dan menyusui', 'obat_80.png', NULL, 'https://tse.mm.bing.net/th?q=Guaifenesin%20obat%20kemasan', 'Batuk', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (81, 'Alpara', 'Batuk Dan Flu', 'Untuk meringankan gejala flu seperti demam, sakit kepala, hidung tersumbat dan bersin-bersin yang disertai batuk', 'Box, Strip', 10500, 'Strip: Rp10.500; Box: Rp109.000', 'Dikonsumsi sesudah makan', 'Anak-anak 6-12 tahun: 12 kaplet, 3 kali sehari; Diatas 12 tahun dewasa: 1 kaplet, 3 kali sehari', 'kantuk; gangguan pencernaan; gangguan psikomotor; takikardia; aritmia; mulut kering; palpitasi; retensi urin; Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan fungsi hati', 'Penggunaan bersama anti depresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan fungsi hati', 'Paracetamol 500 mg; Phenylpropanolamine HCI 12.5 mg; Dextromethorphan HBr 15 mg; Chlorphenamine Maleate 2 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan gangguan jantung dan diabetes mellitus; Penderita dengan gangguan fungsi hati yang berat; Penderita Hipersensitif terhadap komponen obat ini', 'obat_81.png', NULL, 'https://tse.mm.bing.net/th?q=Alpara%20obat%20kemasan', 'Batuk, Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (82, 'Bodrex Flu Batuk PE', 'Batuk Dan Flu', 'Meredakan gejala flu seperti demam, sakit kepala, hidung tersumbat dan bersin-bersin yang disertai batuk tidak berdahak', 'Box, Strip', 2000, 'Strip: Rp2.000; Box: Rp50.500', 'dikonsumsi setelah makanan', 'Dewasa: 1 kaplet 3 kali sehari', 'Gangguan pencernaan; insomnia; gelisah; eksitasi; tremor; takikardia; aritmia; mulut kering; palpitasi dan retensi urin; Penggunaan dosis besar dan jangka panjang dapat menyebabkan kerusakan fungsi hati', 'Penggunaan bersama antidepresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'jika digunakan dalam jangka panjang dan dalam dosis yang tinggi, dapat menimbulkan risiko penyakit ginjal', 'Paracetamol 500 mg; Phenylephrine HCI 10 mg; Dextromethorphan HBr 12 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan gangguan jantung dan diabetes mellitus; Penderita dengan gangguan fungsi hati yang berat', 'obat_82.png', NULL, 'https://tse.mm.bing.net/th?q=Bodrex%20Flu%20Batuk%20PE%20obat%20kemasan', 'Batuk, Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (83, 'Panadol Cold Flu', 'Batuk Dan Flu', 'Untuk meringankan gejala-gejala flu seperti demam, sakit kepala dan hidung tersumbat yang disertai batuk tidak berdahak', 'Box, Strip', 16000, 'Strip: Rp16.000; Box: Rp157.500', 'Dikonsumsi sesudah makan', 'Dewasa: 1 kaplet 13 kali sehari. Jangan diberikan kepada anak-anak di bawah umur 12 tahun, kecuali atas petunjuk dokter.', 'Kadang-kadang dapat menyebabkan tachycardia jantung berdebar, dyspepsia, nausea, kemerahan pada kulit, depresi pernafasan dan susunan saraf pusat, mengantuk, konstipasi, mual, pusing; Gangguan saluran pencernaan, gelisah, eksitasi, tremor; Dapat menyebabkan kantuk dan pusing; Serotonin syndrome sangat jarang terjadi merasa kebingungan, keletihan, berkeringat, genvetar, menggigil, kontraksi otot tiba-tiba atau peningkatan tekanan darah; Halusinasi sangat jarang terjadi. Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan hati', 'Penggunaan bersama antidepresan tipe penghambat Monoamin oksidase MAOIs dapat mengakibatkan krisis hipertensi, Sebelum menggunakan obat ini, konsultasikan dengan dokter atau farmasis mengenai obat lain yang anda konsumsi', 'tidak untuk digunakan dalam jangka panjang', 'Paracetamol 500 mg; Pseudoephedrine HCI 30 mg; Dextromethorphan HBr 15 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan gangguan jantung dan diabetes mellitus; Penderita dengan gangguan fungsi hati yang berat; Jika anda sedang mendapat terapi menggunakan amfetamin umumnya untuk mengatasi attention deficit disorder, penekan nafsu makan, atau obat lain yang mengandung antihistamin. Jika anda memiliki infeksi saluran pernafasan gangguan saluran pernafasan', 'obat_83.png', NULL, 'https://tse.mm.bing.net/th?q=Panadol%20Cold%20Flu%20obat%20kemasan', 'Batuk, Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (84, 'Paramex Flu Batuk PE', 'Batuk Dan Flu', 'Meringankan gejala flu demam, sakit kepala, hidung tersumbat dan batuk tidak berdahak', 'Box, Strip', 3000, 'Strip: Rp3.000; Box: Rp67.500', 'Sesudah makan', 'Anak-anak 6-12 tahun: 3 x sehari 12 tablet; Dewasa: 3 kali sehari 1 tablet', 'Mulut kering; gangguan pencernaan; aritmia; palpitasi; takikardia; tremor; gelisah; insomnia; retensi urin; dan eksitasi; Penggunaan Paracetamol dosis besar dan jangka panjang menyebabkan kerusakan hati', 'Penggunaan bersamaan antidepresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'Jangan mengonsumsi produk Paramex lebih dari 5 hari kecuali disarankan oleh dokter', 'Paracetamol 500 mg; Phenylephrine HCl 10 mg; Dextromethorphan HBr 15 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan gangguan jantung dan diabetes mellitus; Penderita dengan gangguan fungsi hati yang berat; Penderita Hipersensitif terhadap komponen obat ini', 'obat_84.png', NULL, 'https://tse.mm.bing.net/th?q=Paramex%20Flu%20Batuk%20PE%20obat%20kemasan', 'Batuk, Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (85, 'Procold Flu Batuk', 'Batuk Dan Flu', 'Untuk meringankan gejala-gejala flu seperti demam, sakit kepala, hidung tersumbat dan batuk tidak berdahak', 'Box, Strip', 4500, 'Strip: Rp4.500; Box: Rp103.000', 'Berikan setelah makan', 'Dewasa anak 12 tahun: sehari 3 kall 1 kaplet; Anak 6-12 tahun: sehari 3 kali kaplet', 'Gangguan pencernaan; gangguan psikomotor takikardi aritmla palpitasi; retensi urine; mengantuk; Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan hati; mulut kering; Sakit kepala; Insomnia; eksitasi; gelisah; tremor dan sulit berkemih', 'Penggunaan bersama anti depresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'mengonsumsi Procold dalam dosis besar dan jangka panjang bisa menyebabkan gangguan hati yang bisa ditandai dengan mual, lemas, nyeri perut bagian atas, hilang nafsu makan, dan penyakit kuning', 'Paracetamol 500 mg; Dextromethorphan HBr 10 mg; Phenylephrine HC 10 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan gangguan jantung dan diabetes mellitus; Penderita dengan gangguan fungsi hati yang berat; Penderita hipersensitif terhadap salah satu komponen obat', 'obat_85.png', NULL, 'https://tse.mm.bing.net/th?q=Procold%20Flu%20Batuk%20obat%20kemasan', 'Batuk, Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (86, 'Tuzalos', 'Batuk Dan Flu', 'Untuk meringankan gejala-gejala flu seperti demam, sakit kepala, hidung tersumbat dan bersin-bersin yang disertai batuk', 'Box, Strip', 5500, 'Strip: Rp5.500; Box: Rp132.000', 'Dapat diberikan bersama atau tanpa makanan', 'Dewasa: 1 kaplet, 3 kali sehari; Anak-anak 6-12 tahun: 1/2 kaplet, 3 kali sehari', 'Mengantuk; pusing; mulut kering; kejang seperti epilepsi pada dosis besar; ruam kulit', 'Hindari penggunaan Tuzalos bersama dengan obat-obat berikut MAOI, dapat mengakibatkan krisis hipertensi. fluoxetine, paroxetine, quinidine, terbinafine', 'Penggunaan dalam jangka panjang dapat menyebabkan kerusakan hati', 'Dextromethorphan Hydrobromide 10 mg; Phenylpropanolamine Hydrochloride 15 mg; Chlorphenamine Maleate 1 mg; Paracetamol 500 mg', 'Obat ini tidak dianjurkan untuk digunakan oleh penderita penyakit jantung, diabetes mellitus, dan disfungsi hati yang berat, serta pengguna obat anti depresan tipe penghambat monoamin oksidase MAOI', 'obat_86.png', NULL, 'https://tse.mm.bing.net/th?q=Tuzalos%20obat%20kemasan', 'Batuk, Flu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (87, 'Bodrex Flu Batuk Berdahak PE', 'Batuk Dan Flu', 'Meredakan gejala flu seperti , sakit kepala, hidung tersumbat dan bersin-bersin yang disertai batuk berdahak', 'Box, Strip', 2000, 'Strip: Rp2.000; Box: Rp52.500', 'Berikan bersama makanan', 'Dewasa: 1 kaplet 3 kali sehari', 'Gangguan pencemaan; Insomnia; gelisah; eksitasi; tremor; takikardia; aritmia; mulut kering; palpitasi dan retensi urin; Penggunaan dosis besar dan jangka panjang menyebabkan kerusakan hati; Gangguan sistem kekebalan tubuh jarang reaksi hipersensitivitas; belum ada data reaksi anafilaksis termasuk syok anafilaksis, angioederma dan prutitus; Gangguan kulit dan bawah kulit jarang ruam, urtikaria, belum ada data reaksi kulit serius eritema multiforme, sindroma Stevens-Johnsonnekrolisis epidermo toksis dan pustulosis exanthema akut', 'Penggunaan bersama antidepresan tipe penghambat MAO dapat mengakibatkan krisis hipertensi', 'jika digunakan dalam jangka panjang dan dalam dosis yang tinggi, dapat menimbulkan risiko penyakit ginjal', 'Paracetamol 400 mg; Phenylephrine HCI 10 mg; Guaifenesin 100 mg; Bromhexine HCl 8 mg', 'Tidak boleh diberikan pada penderita yang peka terhadap obat simpatomimetik lain misal efedrin, fenilpropanolamin, fenilefrin, penderita tekanan darah tinggi berat, dan yang mendapat terapi obat antidepresan tipe penghambat Monoamin Oksidase MAO; Tidak boleh melebihi dosis yang dianjurkan; Hati-hati penggunaan pada penderita tekanan darah tinggi atau yang mempunyai potensi tekanan darah tinggi atau stroke, seperti pada penderita dengan berat badan berlebih overweight atau penderita usia lanjut; Bila dalam 3 hari gejala flu tidak berkurang segera hubungi dokter atau unit pelayanan kesehatan; Hentikan penggunaan obat ini jika terjadi susah tidur, jantung berdebar dan pusing; Penderita dengan gangguan jantung dan diabetes mellitus; Penderita dengan gangguan fungsi hati yang berat; Penderita Hipersensitif terhadap komponen obat ini', 'obat_87.png', NULL, 'https://tse.mm.bing.net/th?q=Bodrex%20Flu%20Batuk%20Berdahak%20PE%20obat%20kemasan', 'Batuk, Flu', NULL);
