INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (110, 'Ultraflu', 'Flu', 'Meringankan gejala flu seperti demam, sakit kepala, hidung tersumbat dan bersin-bersin', 'Box, Strip', 3500, 'Strip: Rp3.500; Box: Rp72.500', 'Sesudah makan', 'Dewasa dan anak usia 12 tahun: 1 kaplet, 3 kali sehari', 'Dosis besar atau terapi jangka panjang dapat menyebabkan kerusakan hati', 'Interaksi obat dapat terjadi saat Ultraflu dikonsumsi bersama beberapa zat aktif berikut Pemberian bersama dengan kelompok obat monoamine oxidase inhibitors MAOI seperti isocarboxazid; linezolid; phenelzine; rasagiline; selegiline dapat memicu naiknya tekanan darah secara tiba-tiba', 'Penggunaan obat dalam dosis besar dan jangka panjang dapat menyebabkan kerusakan hati', 'paracetamol 600 mg; phenylpropanolamine HCl 15 mg; chlorpheniramine maleate 2 mg', 'Hipersensitif terhadap parasetamol. Pasien dengan disfungsi hati dan ginjal', 'obat_110.png', NULL, 'https://tse.mm.bing.net/th?q=Ultraflu%20obat%20kemasan', 'Flu', NULL);
