INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (132, 'Lacto B sachet', 'Probiotik', 'Menjaga keseimbangan bakteri baik di usus, meringankan gangguan pencernaan, dan mempercepat pemulihan setelah diare atau konsumsi antibiotik. ', 'Sachet/Box', 10000, 'Sachet: ± Rp10.000-12.000', 'Larutkan 1 sachet Lacto B ke dalam segelas air putih, susu, atau makanan anak. Aduk hingga rata dan langsung diminum.', 'Anak 1-12 tahun: 1 sachet, 3 kali sehari.', 'Perut kembung, rasa tidak nyaman di perut namun efek ini bersifat sementara dan akan hilang dengan sendirinya. ', 'Antibiotik dapat menurunkan efektivitas probiotik', 'Sesuai kebutuhan atau anjuran dokter', 'lactobacillus acidophilus, bifidobacterium longum, streptococcus thermophilus, vitamin B1 0,5 mg, vitamin B2 0,5 mg, vitamin B6 0,5 mg, niasin 2 mg, protein 0,02 gram, lemak 0,1 gram, energi total lacto-B 3,4 kalori', 'Alergi terhadap kandungan probiotik, pankreatitis akut berat', NULL, NULL, 'https://www.halodoc.com/obat-dan-vitamin/lacto-b-sachet-1-g', 'Vitamin', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (133, 'Hemaviton Stamina Plus Kapsul', 'Multivitamin & suplemen stamina', 'Membantu memulihkan stamina pria dan wanita. Membantu memelihara daya konsentrasi. Membantu memelihara kesegaran saat bekerja keras maupun olah raga.', 'Strip/Box. Strip Isi 5 Tablet', 8000, 'Sachet: ± Rp8.000-12.000', 'Sebaiknya diminum pada waktu atau setelah makan', '1x1 Sehari', 'Sulit tidur, mual, muntah, sakit perut bila berlebihan', 'Dapat berinteraksi dengan warfarin, aspirin, kafein, ephedrine', 'Umumnya harian sesuai kebutuhan', 'ginseng, guaranine, l-glutamic acid., vitamin a, vitamin c, vitamine, zinc, vitamin b1, vitamin b2, vitamin b5, vitamin b6, vitamin b12', 'Hipersensitif terhadap kandungan produk', NULL, NULL, 'https://www.k24klik.com/p/hemaviton-stamina-plus-kapsul-23365', 'Vitamin', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (134, 'Hemaviton Stamina 1 Botol Isi 30', 'Multivitamin', 'membantu metabolisme tubuh dalam menghasilkan energi, memulihkan stamina, dan memelihara kesegaran', 'Botol', 50000, '50.000-60.000', 'diberikan pada saat makan atau setelah makan', '1x1 Sehari', 'Mual, insomnia', 'Interaksi dengan obat pengencer darah', 'Penggunaan harian', 'Gingseng ekstrak 40 mg, Guaranin 35 mg, L-glutamic acid 200 mg, Antioksidan : Vitamin A 1000 IU, Vitamin C 150 mg, Vitamin E 15 mg, Zinc 15 mg, Multivitamin : Vitamin B1 7,5 mg, Vitamin B2 8,5 mg, Vitamin B3 50 mg, Vitamin B5 10 mg, Vitamin B6 10 mg, Vitamin B12 5 mcg, Folic acid 100 mcg, Mineral : Calcium 100 mg, Phosporus 75 mg, Iron 10 mg, Potassium 2,5 mg', 'Hipersensitivitas', NULL, NULL, 'https://www.halodoc.com/obat-dan-vitamin/hemaviton-stamina-kapsul-30-s', 'Vitamin', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (135, 'Vitamin B1 Ipi', 'Suplemen B1', 'Mencegah dan mengurangi defisiensi vitamin B1', 'Tube', 8000, '8.000-12.000', 'Berikan sesudah makan', NULL, 'Reaksi alergi ringan', 'Dapat dipengaruhi alkohol', 'Sesuai kebutuhan', 'vitamin B1', 'Hipersensitif terhadap vitamin B1', NULL, NULL, 'https://www.k24klik.com/p/ipi-vitamin-b1-tablet-22754', 'Vitamin', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (136, 'Ipi Vitamin D3 1000iu Tablet 1 Boto', 'Vitamin D3 IPI', 'Membantu menjaga kesehatan tulang, gigi dan meningkatkan daya tahan tubuh. Cocok untuk dewasa ataupun lansia yang kurang paparan sinar matahari ataupun defisiensi vitamin D.', 'Botol isi 70 Tablet', 13000, '13.000-15.000', NULL, '1x1 Sehari', 'Mual, konstipasi bila berlebihan', 'Dapat berinteraksi dengan antasida atau suplemen kalsium', 'Penggunaan jangka panjang sesuai dosis', NULL, 'Hiperkalsemia', NULL, NULL, 'https://www.halodoc.com/obat-dan-vitamin/ipi-vitamin-d3-1000-iu-tablet', 'Vitamin', NULL);
