INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (151, 'Bear Brand Rtd Tin Susu 189ml', 'Susu yang terbuat dari 100% susu sapi steril murni', 'untuk kesehatan tubuh', '1 pcs isi 189 ml', 12000, '12.000-14.000', 'langsung dapat diminum, hangat atau dingin. Jangan dimasak hingga mendidih. Hangatkan tanpa melebihi 37 derajat celcius', 'digunakan sesuai dengan kebutuhan', 'Intoleransi laktosa, reaksi alergi susu', NULL, 'Sesuai kebutuhan', '100% susu sapi murni. Lemak total 7gr, lemak jenuh 5,0gr, kolesterol 25mg, protein 6gr, karbohidrat total 9gr, natrium 115mg', 'Alergi susu sapi, intoleransi laktosa berat', NULL, NULL, 'https://www.nestleprofessional.co.id/id/bear-brand', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (152, 'Sgm Ananda Gain 100 0-12bln 400g Box', 'susu formula bayi', 'sebagai nutrisi ekstra untuk pertumbuhan dan perkembangan optimal bayi usia 0-12 bulan. Susu bubuk ini biasa direkomendasikan untuk bayi dengan indikasi gagal tumbuh, gizi kurang ataupun gizi buruk.', 'Box isi 400 g', 108000, '108.000-120.000', 'Disiapkan dengan air matang hangat sesuai petunjuk kemasan. Siapkan larutan susu SGM Ananda Gain 100 hanya untuk 1 kali pemberian. Jangan digunakan lagi untuk pemberian berikutnya bila masih tersisa.', 'Mengikuti tabel pemberian formula', NULL, NULL, 'Sesuai anjuran tenaga kesehatan', 'Maltodekstrin, Campuran minyak nabati (mengandung antioksidan askorbil palmitat), Minyak trigliserida rantai sedang (MCT), Serat pangan, Mineral, Vitamin, Kolin klorida, Minyak sel tunggal (sumber AA)(mengandung antioksidan natrium aksorbat, tokoferol campuran pekat, dan askorbil palmitat), Minyak ikan (sumber DHA) )(mengandung antioksidan natrium askorbat, tokoferol campuran pekat, dan askrobil palmitat), L-Karnitin', 'Tidak cocok untuk bayi atau anak yang tidak mengalami risiko gagal tumbuh, gizi kurang, atau gizi buruk.', NULL, NULL, 'https://www.sgmeksplor.com/', 'Susu', NULL);
