INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (162, 'Mybio Susu Colostrum Sach', 'susu colostrum', 'Membantu meningkatkan sistem kekebalan tubuh (imunitas), membantu menstabilkan tingkat metabolisme yang tidak menentu, membantu menurunkan kadar kolestrol, membantu mencegah penyumbatan pembuluh jantung (penyakit jantung), membantu menurunkan resiko serangan jantung dan stroke, membantu meningkatkan pertumbuhan jaringan tubuh, membantu meningkatkan kualitas tidur, membantu merangsang pertumbuhan tulang yang sehat dan mencegah osteoporosis', 'Dos isi 10 Bungkus', 550000, '550.000-565.000', 'Tuangkan 150 ml air hangat ataupun dingin ke sebuah cangkir. Tuangkan 1 sachet MyBio Kolostrum. Aduk rata dengan sendok plastik. Diminum sebelum makan', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Skim milk powder, colostrum powder, protein gt 45%, asam amino esensial (isoleucine, leucine, histidine, methionine, lysine, threonine, phenylalanine, valine, dan trypthophan), asam amino non-esensial (arginine, cysteine, glutamic acid, alanine, tyrosine, glycine, proline, aspartic acid, dan serine), vitamin (A, B1, B2, niacin, B6, asam pantotenat, asam folat, B12, B3, choline, E, dan C), dan mineral (kalsium/Ca, magnesium/Mg, zinc/Zn, natrium/Na, kalium/K, fosfor/P, zat besi/Fe, yodium/I, dan selenium/Se)', 'Alergi susu', NULL, NULL, 'https://www.k24klik.com/p/mybio-colostrum-24709', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (163, 'Skygoat Susu Kambing Etawa 200g', 'Susu Kambing', 'Melancarkan sistem pencernaan tubuh. Meningkatkan daya tahan tubuh. Mengatasi masalah pada sistem pencernaan tubuh. Berkhasiat pada sistem kecantikan dan kekencangan kulit.', 'Dos isi 200 gr', 38000, '38.000-42.000', 'Masukkan satu sachet SKYGOAT ke dalam gelas. Tuangkan 150ml air hangat. Aduk sampai rata dan siap diminum.', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Krimer Nabati, Susu Bubuk Kambing Etawa Full Cream, Gula, Madu Propolis', 'Alergi susu', NULL, NULL, 'https://skygoat.id/', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (164, 'Entrasol Susu Steril 180ml Kaleng', 'susu steril', 'Menjaga daya tahan tubuh dan Menjaga kesehatan jantung.', 'Kaleng isi 180 ml', 11000, '11.000-13.000', 'Diminum langsung', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Susu segar, air, susu bubuk skim, penstabil nabati, ekstrak buah zaitun, mengandung alergen', 'Alergi susu', NULL, NULL, 'https://www.entrasol.com/', 'Susu, Lansia', NULL);
