INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (169, 'Sgm Bunda Hamil & Menyusui Straw 150g', 'Susu ibu hamil & menyusui', 'kebutuhan nutrisi janin dan Bunda pada masa kehamilan dan menyusui sebagai langkah awal untuk mendukung Generasi Maju.', 'Dos isi 150gr', 25000, '25.000-30.000', 'Dapat disajikan hangat/dingin. Hangat: 180mL air matang hangat + 3 sendok makan (40gr) kemudian aduk rata. Dingin: 70mL air matang hangat + 3 sendok makan (40g). Tambahkan 110mL air dingin atau es batu kemudian aduk rata.', NULL, NULL, NULL, 'Selama masa hamil/menyusui', 'Minyak Ikan, Tinggi Zat Besi (11,2 mg/saji) dan Sumber Protein (8 g/saji), 3, Tinggi Asam Folat (200 mcg/saji) dan Sumber Vitamin B6, Tinggi Kalsium (300 mg/saji), Sumber Vitamin D, dan Sumber Magnesium', 'Alergi susu', NULL, NULL, 'https://www.sgmibudanbalita.com/', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (170, 'Sgm Bunda Hamil & Menyusui Coklat 150g', 'Susu ibu hamil & menyusui', 'kebutuhan nutrisi janin dan Bunda pada masa kehamilan dan menyusui sebagai langkah awal untuk mendukung Generasi Maju.', 'Dos isi 150gr', 26000, '26.000-31.000', 'Dapat disajikan hangat/dingin. Hangat: 180mL air matang hangat + 3 sendok makan (40gr) kemudian aduk rata. Dingin: 70mL air matang hangat + 3 sendok makan (40g). Tambahkan 110mL air dingin atau es batu kemudian aduk rata.', NULL, NULL, NULL, 'Selama masa hamil/menyusui', 'Minyak Ikan, Tinggi Zat Besi (11,2 mg/saji) dan Sumber Protein (8 g/saji), 3, Tinggi Asam Folat (200 mcg/saji) dan Sumber Vitamin B6, Tinggi Kalsium (300 mg/saji), Sumber Vitamin D, dan Sumber Magnesium', 'Alergi susu', NULL, NULL, 'https://www.sgmibudanbalita.com/', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (171, 'Bebelac Gold Soya 3 Vanila 360g Box', 'Susu Formula Soya', 'Susu untuk anak usia di atas 1 tahun. Membantu memenuhi kebutuhan nutrisi anak, terutama anak dengan intoleransi laktosa atau alergi susu sapi', 'Box isi 360 gr', 80000, '80.000-90.000', 'Disajikan menggunakan air hangat sesuai petunjuk kemasan', 'Berilah paling sedikit 3 gelas susu setiap hari selain dari makanan yang biasa dikonsumsi. Siapkan larutan susu hanya untuk satu kali pemberian, dan gunakan langsung formula ini setelah disiapkan. Buang sisa larutan susu soya yang tersisa.', 'Gangguan pencernaan ringan atau alergi kedelai (jarang)', NULL, 'Dapat digunakan selama masa pertumbuhan sesuai kebutuhan nutrisi', 'Maltodextrin, Campuran Minyak Nabati, Isolat Protein Kedelai, Sukrosa, Serat Pangan, 11 Mineral dan Premik Mineral, L-Metionin, 3 Vitamin dan Premik Vitamin, Perisa Sintetik Vanilla, Minyak Ikan (Sumber DHA, Mengandung Antioksidan Tokoferol dan Natrium Askorbat, Kolin Klorida, Taurin, L-Karnitin', 'Tidak cocok untuk bayi dibawah usia 12 Bulan. Konsultasikan dengan dokter anak Anda atau ahli kesehatan lainnya mengenai indikasi alergi pada anak termasuk alergi susu sapi.', NULL, NULL, 'https://www.bebelac.co.id/', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (172, 'Isocal Vanila 400g Box', 'Susu nutrisi lengkap untuk keperluan medis khusus', 'membantu kecukupan gizi dan mendukung daya tahan tubuh yang diperlukan pada masa perawatan dan masa pemulihan usia >1 tahun. Membantu memenuhi kebutuhan nutrisi pasien dengan kebutuhan kalori/protein tambahan', 'Box isi 400gr', 72000, '72.000-80.000', 'Digunakan sesuai petunjuk dokter atau kemasan', 'Sesuai Kebutuhan.', 'Gangguan pencernaan ringan seperti mual atau kembung', NULL, 'Sesuai anjuran tenaga kesehatan', 'Padatan Susu (Susu Bubuk Skim, Laktosa, Susu Sapi, Lemak Susu), Minyak Nabati (Mengandung Antioksidan Askorbil Palmitat), Serat Pangan, Madu, Premiks Mineral dan 3 Mineral, Pengemulsi Lesitin Kedelai, Premiks Vitamin dan Vitamin C, Bubuk Krim, Kolin Bitartrat, Minyak Ikan (mengandung Antioksidan Tokoferol), Perisa Alami, Perisa Sintetik Vanila', 'Alergi terhadap komponen susu sapi atau kedelai', NULL, NULL, 'https://www.nestlehealthscience.co.id/', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (173, 'Lactogen 1 0-6bln 180g Box', 'Susu Formula Bayi', 'susu formula bayi untuk usia 0-6 bulan. Membantu memenuhi kebutuhan nutrisi bayi ketika ASI tidak mencukupi', 'Box isi 180gr', 35000, '35.000-40.000', 'Setiap penyajian hanya untuk sekali pemberian. berikan sesegera mungkin dan ikuti petunjuk dengan tepat. Apabila tidak habis, buang sisa Formula Bayi yang ada dalam botol. Pegang bayi setiap kali menyusui. Meninggalkan bayi tanpa pengawasan dapat menyebabkan bayi tersedak. Disiapkan dengan peralatan steril dan diberikan segera setelah dibuat', NULL, 'Ikuti petunjuk pada kemasan', 'Gangguan pencernaan ringan atau alergi protein susu', 'Digunakan selama usia 0–6 bulan sesuai kebutuhan', 'Padatan susu (laktosa, bubuk whey, susu bubuk skim), campuran minyak nabati (mengandung antioksidan tokoferol dan askorbil palmitati), inulin, 8 mineral, dan premiks mineral, minyak LC-PUFA (mengandung minyak ikan (DHA), ARA, mengandung antioksidan tokoferol dan askorbil palmitat), pengemulsi lesitin kedelai, premiks vitamin, L, reuteri DSM 17938, L,karnitin', 'Tidak digunakan bila bayi alergi protein susu sapi', NULL, NULL, 'https://www.lactogrow.co.id/', 'Susu', NULL);
INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (174, 'Nestle Peptamen Junior 400g', 'Susu Formula Anak', 'Produk susu untuk anak 1-10 tahun yang kaya kebaikan protein whey dengan nutrisi lengkap yang dapat membantu mempercepat masa pemulihan dan mempersingkat masa perawatan si kecil. PEPTAMEN JUNIOR tepat diberikan untuk kondisi:Bermasalah dengan pengosongan lambung, Stres metabolik meningkat, Penyakit kritis / pasien ICU, Pasien trauma, luka bakar, kanker, sepsis / infeksi, operasi, Malnutrisi / berisiko malnutrisi, Gagal tumbuh, Intoleransi saluran cerna termasuk diare kronis dan short-bowel syndrome, Tidak dapat menyerap lemak / pasien Atresia bilier, dan Kelainan Pankreas.', 'Box Isi 400gr', 360000, '360.000-380.000', 'Tambahkan 55 g bubuk (7 sendok takar) ke dalam 210 ml air bersih bersuhu < 45°C', 'Sesuai Kebutuhan', 'Diare, mual, kembung', NULL, 'Sesuai anjuran dokter', 'Maltodekstrin, Protein Whey (Susu Sapi) terhidrolisa dengan enzim Alkalase, Gula, MCT (Medium CHain Triglyceride), Pati Kentang, Campuran Minyak Nabati (mengandung Antioksidan Palmitat), 7 Mineral dan Premiks Mineral, Pengemulsi Lesitin Kedelai, Perisa Sintetik Vanila, Pengatur Keasaman Asam Sitrat, Premiks Vitamin, Kolin, L-karnitin', 'Hipersensitivitas terhadap komponen produk', NULL, NULL, 'https://www.nestlehealthscience.co.id/', 'Susu', NULL);
