INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (183, 'Pil Kb Andalan Fe', 'pil KB', 'Sebagai kontrasepsi oral untuk mencegah kehamilan', 'Dos', 26000, '26.000-30000', NULL, 'Mulai minum pada saat pertama haid sesuai dengan petunjuk pada bagian belakang blister dan dikonsumsi setiap hari dan pada waktu (jam) yang sama', 'Efek samping yang biasanya muncul adalah spotting pada 3 bulan pertama, pusing, mual, payudara terasa lebih lembek. Pada umumnya efek samping ini akan berangsur hilang setelah beberapa kali penggunaan.', NULL, NULL, 'Levonorgestrel 0,15 mg, ethinylestradiol 0,03 mg plus placebo tab contains Fe fumarate 75 mg', NULL, NULL, NULL, 'https://www.sahabatandalan.com/detail-produk/perencanaan-keluarga/pil-kb/pil-kb-andalan-fe/', '*Kontrasepsi', NULL);
