INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (185, 'Pil Kb Andalan Fe', 'pil KB', 'Sebagai kontrasepsi oral untuk mencegah kehamilan', 'Dos', 30000, '30.000-35.000', 'Diminum dalam waktu paling lambat 5 (lima) hari atau tidak lebih dari 120 jam setelah berhubungan tanpa perlindungan alat kontrasepsi.', 'Diminum dua tablet sekaligus', 'Efek samping yang biasanya muncul adalah mual, sakit kepala, pusing dan payudara terasa lebih keras. Pada umumnya efek samping tidak berlangsung lebih dari 24 jam. Apabila terjadi muntah dalam waktu satu jam, maka dianjurkan untuk minum satu pil terlebih dahulu dan minum pil kedua 12 jam setelah meminum tablet yang pertama.', NULL, 'Semakin cepat diminum, semakin tinggi tingkat keefektivitasannya. Hanya digunakan di saat darurat tanpa perlindungan kontrasepsi regular kontrasepsi', '2 tablet di setiap kemasan masing-masing berisi 0,75 mg Levonorgestrel (hormon progestin)', NULL, NULL, NULL, 'https://www.sahabatandalan.com/detail-produk/perencanaan-keluarga/kontrasepsi-darurat/postpil/', '*Kontrasepsi', NULL);
