INSERT INTO `obat` (`id_obat`, `nama_obat`, `kategori_penyakit`, `indikasi`, `satuan_tersedia`, `harga_mulai`, `harga_detail`, `aturan_pemakaian`, `dosis`, `efek_samping`, `interaksi_obat`, `jangka_waktu_penggunaan`, `komposisi`, `kontra_indikasi`, `image`, `stok`, `image_url_direct`, `kategori`, `col19`) VALUES (202, 'Rivanol Molex Ayus 100ml', 'cairan antiseptik', 'untuk penyembuhan dan pembersih pada luka agar tidak terjadi infeksi berkelanjutan. sering digunakan dalam proses perawatan dan penyembuhan luka sayat karena memiliki sifat bakteriostatik (menghambat pertumbuhan kuman) dan tidak bersifat iritatif pada kulit sehingga cocok sebagai antiseptik borok bernanah, kompres, dan irigasi luka terinfeksi.', 'Botol', 7000, '7.000-10.000', 'Bubuhkan rivanol pada kapas, kemudian usapkan pada luka. bisa untuk membasuh luka', 'Sesuai kebutuhan.', NULL, NULL, NULL, 'Etakridina laktat', NULL, NULL, NULL, 'https://www.tokopedia.com/search?q=rivanol%20molex%20ayus%20100ml', 'Antiseptik', NULL);
